  '\\nPending transfer notification sent:%s.\\n' => 'Notificación de transferencia pendiente enviada: %s.',
  '\\nWooCommerce checks\\n' => 'Comprobaciones de WooCommerce',
  'This check could not run: %s' => 'Esta verificación no se pudo ejecutar: %s',
  '\\nVersion%1$sis active. Flux Donate was checked up to%2$s; it uses only stable public WooCommerce functions, but test a donation after big WooCommerce updates.\\n' => 'La versión%1$sestá activa. Flux Donate se comprobó en%2$s; solo utiliza funciones públicas estables de WooCommerce, pero prueba una donación después de grandes actualizaciones de WooCommerce.',
